record.field:
for rec in records.sudo():
    employee = rec.x_employee_id.sudo() if rec.x_employee_id else False
    custody_type = rec.x_custody_type_id.sudo() if rec.x_custody_type_id else False

    employee_name = employee.name or employee.display_name or 'Employee'
    type_name = custody_type.x_name if custody_type else 'Custody'
    type_code = custody_type.x_code if custody_type and custody_type.x_code else 'CUST'

    vals = {}
    if not rec.x_state:
        vals['x_state'] = 'draft'
    if not rec.x_quantity:
        vals['x_quantity'] = 1
    if not rec.x_responsible_user_id:
        vals['x_responsible_user_id'] = env.user.id
    if not rec.x_clearance_status:
        vals['x_clearance_status'] = 'pending'
    if rec.x_clearance_required is False:
        vals['x_clearance_required'] = True

    if not rec.x_reference_code:
        emp_part = employee.id if employee else 0
        vals['x_reference_code'] = 'MCEP-HR-%s-EMP-%05d-%05d' % (type_code, emp_part, rec.id)

    reference = vals.get('x_reference_code') or rec.x_reference_code or ''
    if not rec.x_document_reference:
        vals['x_document_reference'] = reference

    item_hint = rec.x_item_identifier or rec.x_serial_number or rec.x_document_reference or reference
    normalized_name = '%s - %s - %s' % (employee_name, type_name, item_hint)
    if rec.x_name != normalized_name:
        vals['x_name'] = normalized_name

    if vals:
        rec.write(vals)

    if employee:
        employee.message_post(
            body='تم تحديث العهدة: %s' % (vals.get('x_name') or rec.x_name or normalized_name),
            subtype_xmlid='mail.mt_note',
        )

